function matchesSearch(item) { return !state.search || JSON.stringify(item).toLowerCase().includes(state.search); }
function currentDomainId() { return Object.entries(DOMAIN_META).find(([, meta]) => meta.view === state.view)?.[0] || ""; }
function domainName(domainId) { return DOMAIN_META[domainId]?.name || shortDomainName((state.data?.domains || []).find((item) => item.id === domainId) || { id: domainId }); }
function ownersFor(kind, typeId) { return state.data?.domain_ownership?.[kind]?.[typeId] || []; }
function primaryOwner(kind, typeId) { return ownersFor(kind, typeId)[0] || "shared"; }

function amountOf(value) { return value && typeof value === "object" ? Number(value.amount || 0) : Number(value || 0); }
function money(value, currency = "CNY") { const amount = amountOf(value); if (!Number.isFinite(amount)) return "-"; try { return new Intl.NumberFormat("zh-CN", { style: "currency", currency, maximumFractionDigits: 2 }).format(amount); } catch { return `${amount.toFixed(2)} ${currency}`; } }
function sumMoney(items, field) { const total = items.reduce((sum, item) => sum + amountOf(item.properties?.[field]), 0); return money(total); }
function objectById(id) { return indexObjects()[id]; }
function outgoing(id, type, role) { return (state.data?.relations || []).filter((rel) => rel.from === id && (!type || rel.type === type) && (!role || rel.properties?.role === role)); }
function incoming(id, type, role) { return (state.data?.relations || []).filter((rel) => rel.to === id && (!type || rel.type === type) && (!role || rel.properties?.role === role)); }
function targets(id, type, role) { return outgoing(id, type, role).map((rel) => objectById(rel.to)).filter(Boolean); }
function firstTarget(id, type, role) { return targets(id, type, role)[0]; }
function uniqueObjects(items) { return [...new Map(items.filter(Boolean).map((item) => [item.id, item])).values()]; }
function passageFacts(passage) {
  const events = targets(passage.id, "contains").filter((item) => item.type === "passage_event").sort((a, b) => String(a.properties?.occurred_at || "").localeCompare(String(b.properties?.occurred_at || "")));
  const charge = targets(passage.id, "derives").find((item) => item.type === "charge") || null;
  const vehicle = firstTarget(passage.id, "associates", "passage_vehicle"); const medium = firstTarget(passage.id, "references", "used_medium");
  const entry = events.find((item) => item.properties?.stage === "entry"); const exit = events.find((item) => item.properties?.stage === "exit");
  const payments = charge ? incomingTargets(charge.id, "references").filter((item) => item.type === "payment") : [];
  const splits = charge ? targets(charge.id, "derives").filter((item) => item.type === "split_result") : [];
  const clearings = uniqueObjects(splits.flatMap((split) => targets(split.id, "derives").filter((item) => item.type === "clearing_result")));
  const settlements = uniqueObjects(clearings.flatMap((clearing) => targets(clearing.id, "derives").filter((item) => item.type === "settlement")));
  const allocations = uniqueObjects(settlements.flatMap((settlement) => targets(settlement.id, "derives").filter((item) => item.type === "allocation")));
  return { events, charge, vehicle, medium, entry, exit, payments, splits, clearings, settlements, allocations, split: splits[0] || null, settlement: settlements[0] || null, complete: Boolean(entry && exit && charge) };
}

